// Version 0.3.0. Every hex here is read from the shipped CSS through the same cascade the
// web uses, so a SwiftUI view and a web page with the same axes resolve identical colour.
import SwiftUI

public enum FlavorHue: String, CaseIterable { case brand, brand2, neutral, red, scarlet, orange, tangerine, yellow, lime, green, teal, cyan, blue, violet, purple, magenta }
public enum FlavorSaturation: String, CaseIterable { case muted, regular, bold }
public enum FlavorContrast: String, CaseIterable { case aa, aaa }
public enum FlavorBackground: String, CaseIterable { case primary = "primary"; case secondary = "secondary"; case darkPrimary = "dark-primary"; case darkSecondary = "dark-secondary"; case accent = "accent"; case media = "media" }
public enum FlavorRadius: String, CaseIterable { case square, rounded, pill }
public enum FlavorDensity: String, CaseIterable { case compact, regular, comfy }

/// The theme axes. Light/dark is NOT an axis here — it follows the environment's ColorScheme,
/// which is what a native app should do; pass `scheme` from `@Environment(\.colorScheme)`.
public struct FlavorTheme: Hashable {
  public var hue: FlavorHue = .brand
  public var saturation: FlavorSaturation = .regular
  public var contrast: FlavorContrast = .aa
  public var background: FlavorBackground = .primary
  public var radius: FlavorRadius = .rounded
  public var density: FlavorDensity = .regular
  public init() {}
  public init(hue: FlavorHue, saturation: FlavorSaturation = .regular, contrast: FlavorContrast = .aa, background: FlavorBackground = .primary, radius: FlavorRadius = .rounded, density: FlavorDensity = .regular) {
    self.hue = hue; self.saturation = saturation; self.contrast = contrast; self.background = background; self.radius = radius; self.density = density
  }
  var key: String { "\(hue.rawValue)/\(saturation.rawValue)/\(contrast.rawValue)/\(background.rawValue)" }
}

